import{_ as e,o as l,c as a,ag as i}from"./chunks/framework.DXGyWiRo.js";const c=JSON.parse('{"title":"知识点6：物联网与传感器","description":"","frontmatter":{"title":"知识点6：物联网与传感器"},"headers":[],"relativePath":"high-school-it/knowledge-6.md","filePath":"high-school-it/knowledge-6.md"}'),n={name:"high-school-it/knowledge-6.md"};function r(d,t,o,s,h,g){return l(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="知识点6-物联网与传感器" tabindex="-1">知识点6：物联网与传感器 <a class="header-anchor" href="#知识点6-物联网与传感器" aria-label="Permalink to &quot;知识点6：物联网与传感器&quot;">​</a></h1><h2 id="一、物联网三层架构" tabindex="-1">一、物联网三层架构 <a class="header-anchor" href="#一、物联网三层架构" aria-label="Permalink to &quot;一、物联网三层架构&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">层次</th><th style="text-align:left;">功能</th><th style="text-align:left;">包含内容</th></tr></thead><tbody><tr><td style="text-align:center;">感知层</td><td style="text-align:left;">采集物理世界信息</td><td style="text-align:left;">传感器、GPS、摄像头、RFID</td></tr><tr><td style="text-align:center;">网络层</td><td style="text-align:left;">数据传输</td><td style="text-align:left;">移动通信网络、互联网、WiFi</td></tr><tr><td style="text-align:center;">应用层</td><td style="text-align:left;">数据处理与用户交互</td><td style="text-align:left;">调度系统、用户界面、应用程序</td></tr></tbody></table><h2 id="二、传感器" tabindex="-1">二、传感器 <a class="header-anchor" href="#二、传感器" aria-label="Permalink to &quot;二、传感器&quot;">​</a></h2><p><strong>定义</strong>：将采集到的物理量或化学量转换为信息系统能够处理的数据。</p><p><strong>工作过程</strong>：敏感与转换元件 → 信号调节电路 → 模数转换电路 → 数字信号输出</p><p><strong>关键知识点</strong>：</p><ul><li>传感器属于物联网感知层（不是应用层）</li><li>传感器数据采集是信息系统的输入方式之一</li><li>传感器支持长期、连续的数据采集，适用于环境监测</li></ul><h2 id="三、自动识别技术" tabindex="-1">三、自动识别技术 <a class="header-anchor" href="#三、自动识别技术" aria-label="Permalink to &quot;三、自动识别技术&quot;">​</a></h2><ul><li><strong>RFID（射频识别）</strong>：通过无线电波自动读取电子标签信息，无需电池供电</li></ul><hr><h2 id="四、真题" tabindex="-1">四、真题 <a class="header-anchor" href="#四、真题" aria-label="Permalink to &quot;四、真题&quot;">​</a></h2><p><strong>1.（2025-01，综合题二）</strong> 以下是水质监测系统所在的物联网基本架构，请协助小申选择左侧框图拖动至右侧合适的虚线框中。（填空题，6分）</p><p>考点：感知层、网络层、应用层的对应匹配</p><p><strong>2.（2025-01，综合题二）</strong> 水质监测系统用到了各类传感器。关于传感器，以下说法正确的有（ ）（多选题，3分）</p><ul><li>A. 传感器的工作目标是将采集到的物理量或化学量转换成信息系统所能够处理的数据</li><li>B. 传感器采集数据是在物联网的应用层中实现的</li><li>C. 传感器数据采集是信息系统的输入方式之一</li><li>D. 传感器支持长期、连续的数据采集，适用于环境监测等应用</li></ul><p><strong>3.（浦东新区2025，综合题一）</strong> 在科技馆彩虹儿童乐园中，小朋友佩戴的&quot;彩虹手镯&quot;内嵌有无源电子标签。当靠近互动装置时，装置通过无线电波自动读取标签信息，无需电池供电。这种自动识别技术是__________。（填空题，2分）</p><p><strong>4.（浦东新区2025，综合题二）</strong> 近期学校引进了智能取餐柜，学生凭手机上的订单二维码扫码取餐。小申查阅了以下相关资料，了解到该取餐柜扫码设备所使用的传感器是__________。（填空题，2分）</p><table tabindex="0"><thead><tr><th style="text-align:center;">扫描类型</th><th style="text-align:center;">传感器</th><th style="text-align:center;">适用码制</th><th style="text-align:center;">扫描对象</th><th style="text-align:center;">应用场景</th></tr></thead><tbody><tr><td style="text-align:center;">激光扫描</td><td style="text-align:center;">光电传感器</td><td style="text-align:center;">一维码</td><td style="text-align:center;">纸质条码</td><td style="text-align:center;">传统超市收银台</td></tr><tr><td style="text-align:center;">影像式扫描</td><td style="text-align:center;">图像传感器</td><td style="text-align:center;">一维码/二维码</td><td style="text-align:center;">纸质条码/手机屏幕码</td><td style="text-align:center;">智能零售、移动支付</td></tr></tbody></table><p><strong>5.（浦东新区2025，综合题二）</strong> 食堂后厨冷库安装了温湿度传感器，用于实时监测食材储存环境是否达标。一旦温度或湿度超出设定范围，系统会自动向管理员发送警报。温湿度传感器的主要部件有①模数转换电路 ②敏感与转换元件 ③信号调节电路。（5分）</p><p>（1）请在横线处从左往右依次填入部件序号：__________。（只填数字，示例：1 2 3）</p><p>（2）这里的温湿度传感器，属于物联网基本架构中的（ ）</p><ul><li>A. 网络层</li><li>B. 应用层</li><li>C. 感知层</li><li>D. 接收层</li></ul><h3 id="答案" tabindex="-1">答案 <a class="header-anchor" href="#答案" aria-label="Permalink to &quot;答案&quot;">​</a></h3><ol><li>考点：感知层、网络层、应用层的对应匹配</li><li>ACD（传感器属于感知层，不是应用层）</li><li>RFID 或 射频识别技术</li><li>图像传感器</li><li>（1）2 3 1；（2）C（传感器工作顺序：敏感元件→信号调节→模数转换；属于感知层）</li></ol>',25)])])}const x=e(n,[["render",r]]);export{c as __pageData,x as default};
